package com.zhuqiyun.exchange;
import com.zhuqiyun.platform.*;import com.zhuqiyun.project.ProjectService;
import org.apache.poi.ss.usermodel.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
import java.util.*;import java.util.zip.*;import java.io.*;import java.math.BigDecimal;import java.security.MessageDigest;
import static com.zhuqiyun.domain.Rules.row;
@Service
public class ImportService {
 private final Db db;private final Auth auth;private final MasterController master;private final ProjectService projects;
 public ImportService(Db db,Auth auth,MasterController master,ProjectService projects){this.db=db;this.auth=auth;this.master=master;this.projects=projects;}
 public static LinkedHashMap<String,String> columns(String kind){String[][] pairs=switch(kind){case "suppliers"->new String[][]{{"code","供应商编号"},{"name","供应商名称"},{"contact","联系人"},{"phone","联系电话"},{"category","供应类别"},{"status","状态 ACTIVE/INACTIVE"},{"qualification","资质说明"},{"qualification_expiry","资质有效期 yyyy-MM-dd"},{"rating","评级 0-5"}};case "materials"->new String[][]{{"code","材料编号"},{"name","材料名称"},{"specification","规格"},{"unit","单位"},{"category","分类"},{"safety_stock","安全库存"},{"reference_price","参考单价"}};case "warehouses"->new String[][]{{"code","仓库编号"},{"name","仓库名称"},{"location","仓库地址"}};case "projects"->new String[][]{{"code","项目编号"},{"name","项目名称"},{"owner","建设单位"},{"contractor","承建单位"},{"manager_username","负责人登录名"},{"location","位置"},{"type","项目类型"},{"contract_amount","合同金额"},{"budget_amount","预算金额"},{"start_date","开工日期 yyyy-MM-dd"},{"end_date","完工日期 yyyy-MM-dd"},{"progress","进度 0-100"},{"status","状态 PLANNING/ACTIVE/COMPLETED/SUSPENDED"}};default->throw new ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"仅支持供应商、材料、项目、仓库新增导入");};LinkedHashMap<String,String> map=new LinkedHashMap<>();for(var pair:pairs)map.put(pair[0],pair[1]+" ["+pair[0]+"]");return map;}
 private void permission(String kind){columns(kind);auth.require(kind.equals("projects")?"project:write":"master:write");if(kind.equals("projects")){auth.require("cost:read");auth.require("contract:read");}}
 public byte[] template(String kind){permission(kind);try(var book=new XSSFWorkbook();var out=new ByteArrayOutputStream()){var sheet=book.createSheet("导入数据");var header=sheet.createRow(0);var text=book.createCellStyle();text.setDataFormat(book.createDataFormat().getFormat("@"));int i=0;for(var column:columns(kind).entrySet()){header.createCell(i).setCellValue(column.getValue());if(Set.of("code","phone","manager_username").contains(column.getKey()))sheet.setDefaultColumnStyle(i,text);sheet.setColumnWidth(i++,24*256);}sheet.createFreezePane(0,1);var help=book.createSheet("填写说明");String[] lines={"仅新增，不覆盖已有记录。请保留首行表头，在导入数据页第2行起填入数据。","每次最多300行；仅接受xlsx，不接受公式或宏。编号、电话等请使用文本格式。","日期必须为yyyy-MM-dd或Excel日期单元格；金额最多2位，参考单价4位，数量3位。","材料单位、分类必填；项目负责人用启用的项目经理或负责人登录名，经理只能指定本人。","供应商可省略状态及评级（默认为ACTIVE、4.5）；项目可省略进度及状态（默认为0、PLANNING）。","导入前先预览，所有行通过后上传同一文件正式导入；服务端会重新校验，任何错误整批不写入。","本轮不支持期初库存导入，材料参考价不会生成库存、流水或项目成本。"};for(int n=0;n<lines.length;n++)help.createRow(n).createCell(0).setCellValue(lines[n]);help.setColumnWidth(0,110*256);book.write(out);return out.toByteArray();}catch(IOException e){throw new IllegalStateException(e);}}
 private void zipCheck(byte[] data){Fields.check(data.length>0&&data.length<=2*1024*1024,"文件大小须在2MB以内");try(var zip=new ZipInputStream(new ByteArrayInputStream(data))){int count=0;long total=0;byte[] buffer=new byte[8192];ZipEntry entry;boolean content=false;while((entry=zip.getNextEntry())!=null){Fields.check(++count<=200,"文件内容过多");String name=entry.getName().toLowerCase(Locale.ROOT);Fields.check(!name.contains("vbaproject")&&!name.contains("externallinks"),"不接受宏或外部链接");if(name.equals("[content_types].xml"))content=true;int n;while((n=zip.read(buffer))!=-1){total+=n;Fields.check(total<=20*1024*1024,"文件解压后过大");}}Fields.check(content,"请上传标准xlsx文件");}catch(IOException e){Fields.check(false,"xlsx文件损坏");}}
 private String hash(byte[] bytes){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(Exception e){throw new IllegalStateException(e);}}
 private String value(Cell c){if(c==null||c.getCellType()==CellType.BLANK)return "";Fields.check(c.getCellType()!=CellType.FORMULA,"不接受公式单元格，请粘贴为值");Fields.check(c.getCellType()!=CellType.ERROR,"单元格包含错误");if(c.getCellType()==CellType.NUMERIC){if(DateUtil.isCellDateFormatted(c))return c.getLocalDateTimeCellValue().toLocalDate().toString();return BigDecimal.valueOf(c.getNumericCellValue()).stripTrailingZeros().toPlainString();}return Fields.text(c.getStringCellValue(),1000,false);}
 public Map<String,Object> preview(String kind,byte[] bytes){permission(kind);zipCheck(bytes);List<Map<String,Object>> result=new ArrayList<>();var columns=columns(kind);Set<String> codes=new HashSet<>();try(var book=new XSSFWorkbook(new ByteArrayInputStream(bytes))){var sheet=book.getSheet("导入数据");Fields.check(sheet!=null,"缺少导入数据工作表，请使用模板");Fields.check(sheet.getLastRowNum()<=300,"每批最多300行");var header=sheet.getRow(0);Fields.check(header!=null,"缺少模板表头");int column=0;for(String label:columns.values())Fields.check(label.equals(value(header.getCell(column++))),"模板表头不匹配，请重新下载模板");
  for(int r=1;r<=sheet.getLastRowNum();r++){var input=sheet.getRow(r);if(input==null)continue;Map<String,Object> data=new LinkedHashMap<>();List<String> errors=new ArrayList<>();column=0;boolean nonempty=false;for(String key:columns.keySet()){try{String v=value(input.getCell(column++));if(!v.isBlank()){data.put(key,v);nonempty=true;}}catch(ResponseStatusException e){errors.add(e.getReason());nonempty=true;}}if(!nonempty)continue;
   for(Cell c:input)if(c.getColumnIndex()>=columns.size()&&c.getCellType()!=CellType.BLANK)errors.add("含模板以外的数据列");
   String code=Objects.toString(data.get("code"),"").toLowerCase(Locale.ROOT);if(!codes.add(code))errors.add("文件内编号重复");if(!code.isEmpty()&&!db.list("SELECT id FROM "+kind+" WHERE tenant_id=1 AND LOWER(code)=? LIMIT 1",code).isEmpty())errors.add("编号已存在；仅新增，不覆盖");
   Map<String,Object> inputData=new LinkedHashMap<>(data);try{data=validate(kind,data);}catch(ResponseStatusException e){errors.add(Objects.toString(e.getReason(),"校验失败"));}result.add(row("row",r+1,"data",data,"input",inputData,"errors",errors));
  }
 }catch(ResponseStatusException e){throw e;}catch(Exception e){Fields.check(false,"无法解析xlsx，请检查格式及单元格类型");}
 Fields.check(!result.isEmpty(),"文件没有可导入的数据");boolean valid=result.stream().allMatch(r->((List<?>)r.get("errors")).isEmpty());long invalid=result.stream().filter(r->!((List<?>)r.get("errors")).isEmpty()).count();return row("hash",hash(bytes),"rows",result,"columns",columns,"valid",valid,"strategy","CREATE_ONLY","count",result.size(),"valid_count",result.size()-invalid,"error_count",invalid);}
 private Map<String,Object> validate(String kind,Map<String,Object> raw){var data=new LinkedHashMap<>(raw);if(kind.equals("projects")){Object username=data.remove("manager_username");Fields.check(username!=null,"负责人登录名必填");var users=db.list("SELECT id FROM users WHERE username=? AND tenant_id=1 AND enabled=TRUE",username);Fields.check(users.size()==1,"负责人不存在或已停用");data.put("manager_id",users.get(0).get("id"));return projects.validateNew(data);}return master.validateNew(kind,data);}
 @Transactional public Map<String,Object> commit(String kind,byte[] bytes,String expected){permission(kind);Fields.check(hash(bytes).equals(expected),"文件与预览不一致，请重新预览");var preview=preview(kind,bytes);Fields.check(Boolean.TRUE.equals(preview.get("valid")),"存在逐行错误，本批次未写入，请重新预览");Fields.check(db.list("SELECT id FROM import_batches WHERE tenant_id=1 AND entity_type=? AND file_hash=?",kind,expected).isEmpty(),"该文件已经导入，不会覆盖记录");long batch=db.insert("import_batches",row("entity_type",kind,"file_hash",expected,"row_count",preview.get("count"),"operator_id",auth.id()));for(var entry:(List<Map<String,Object>>)preview.get("rows")){var data=(Map<String,Object>)entry.get("data");if(kind.equals("projects"))projects.create(data);else if(kind.equals("suppliers"))master.createSupplier(data);else if(kind.equals("materials"))master.createMaterial(data);else master.createWarehouse(data);}auth.audit("IMPORT_CREATE_ONLY",kind,batch,"新增 "+preview.get("count")+" 行 SHA256 "+expected);return row("batch_id",batch,"created",preview.get("count"));}
}
